"use strict";

// Classic browser script: load before any UI or validator that uses KomiGame.
const KomiGame = (() => {
  const WINNING_LINES = Object.freeze([
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6],
  ].map(Object.freeze));

  const OUTCOME = Object.freeze({
    ACTIVE: "ACTIVE",
    X_WIN: "X_WIN",
    O_WIN: "O_WIN",
    O_KOMI: "O_KOMI",
  });

  // Board indices are row-major, 0..8; null represents an empty square.
  // Accepts reachable boards. Normal wins must be checked before fullness.
  function evaluateBoard(board) {
    for (const [a, b, c] of WINNING_LINES) {
      if (board[a] !== null && board[a] === board[b] && board[a] === board[c]) {
        return board[a] === "X" ? OUTCOME.X_WIN : OUTCOME.O_WIN;
      }
    }
    return board.every(cell => cell !== null) ? OUTCOME.O_KOMI : OUTCOME.ACTIVE;
  }

  function makeState(board, nextPlayer, outcome) {
    return Object.freeze({ board: Object.freeze(board), nextPlayer, outcome });
  }

  function createGame() {
    return makeState(Array(9).fill(null), "X", OUTCOME.ACTIVE);
  }

  // State arguments come from createGame() or successful playMove() calls.
  function getLegalMoves(state) {
    if (state.outcome !== OUTCOME.ACTIVE) return [];
    return state.board.flatMap((cell, index) => cell === null ? [index] : []);
  }

  // Rejections retain the exact state object. Terminal states have no next player.
  function playMove(state, index) {
    if (state.outcome !== OUTCOME.ACTIVE) {
      return { accepted: false, state, reason: "TERMINAL" };
    }
    if (!Number.isInteger(index) || index < 0 || index > 8) {
      return { accepted: false, state, reason: "INVALID_SQUARE" };
    }
    if (state.board[index] !== null) {
      return { accepted: false, state, reason: "OCCUPIED" };
    }

    const board = state.board.slice();
    board[index] = state.nextPlayer;
    const outcome = evaluateBoard(board);
    const nextPlayer = outcome === OUTCOME.ACTIVE
      ? (state.nextPlayer === "X" ? "O" : "X")
      : null;
    return { accepted: true, state: makeState(board, nextPlayer, outcome), reason: null };
  }

  return Object.freeze({ WINNING_LINES, OUTCOME, createGame, evaluateBoard, getLegalMoves, playMove });
})();
"use strict";

(() => {
  const cells = document.querySelectorAll("#board button[data-index]");
  const status = document.getElementById("status");
  const playAgain = document.getElementById("play-again");
  const resultMessages = {
    [KomiGame.OUTCOME.X_WIN]: "Player X won",
    [KomiGame.OUTCOME.O_WIN]: "Player O won",
    [KomiGame.OUTCOME.O_KOMI]: "Player O won with Komi",
  };
  let state = KomiGame.createGame();

  function render() {
    const legalMoves = KomiGame.getLegalMoves(state);
    cells.forEach(cell => {
      const index = Number(cell.dataset.index);
      const mark = state.board[index];
      cell.textContent = mark ?? "";
      cell.disabled = !legalMoves.includes(index);
      cell.setAttribute("aria-label",
        `Row ${Math.floor(index / 3) + 1}, column ${index % 3 + 1}, ${mark ?? "empty"}`);
    });
    const active = state.outcome === KomiGame.OUTCOME.ACTIVE;
    status.textContent = active
      ? `Player ${state.nextPlayer}'s turn`
      : resultMessages[state.outcome];
    playAgain.hidden = active;
  }

  cells.forEach(cell => {
    cell.addEventListener("click", () => {
      state = KomiGame.playMove(state, Number(cell.dataset.index)).state;
      render();
    });
  });

  playAgain.addEventListener("click", () => {
    state = KomiGame.createGame();
    render();
    cells[0].focus();
  });

  render();
})();
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Komi Tic-Tac-Toe</title>
    <style>
        body { margin: 0; font-family: system-ui, sans-serif; color: #202020; background: #fafafa; }
        main { max-width: 28rem; margin: 3rem auto; padding: 0 1rem; }
        h1 { font-size: 1.8rem; }
        p { line-height: 1.5; }
        #status { font-size: 1.2rem; font-weight: bold; }
        #board { display: grid; grid-template-columns: repeat(3, 1fr); gap: .5rem; max-width: 20rem; }
        button { font: inherit; cursor: pointer; }
        #board button { aspect-ratio: 1; font-size: 2.5rem; border: 2px solid #666; border-radius: .25rem; background: white; color: #202020; }
        #board button:disabled { cursor: default; background: #ececec; opacity: 1; }
        button:focus-visible { outline: 3px solid #145bcc; outline-offset: 3px; }
        #play-again { margin-top: 1rem; padding: .6rem 1rem; }
    </style>
    <script src="game.js" defer></script>
    <script src="app.js" defer></script>
</head>
<body>
    <main>
        <h1>Komi Tic-Tac-Toe</h1>
        <p>Two players share this board. X starts. If the board fills without three in a row, O wins the Komi tiebreak.</p>
        <p id="status" role="status" aria-live="polite" aria-atomic="true"></p>
        <div id="board" role="group" aria-label="Tic-tac-toe board">
            <button type="button" data-index="0" aria-label="Row 1, column 1, empty"></button>
            <button type="button" data-index="1" aria-label="Row 1, column 2, empty"></button>
            <button type="button" data-index="2" aria-label="Row 1, column 3, empty"></button>
            <button type="button" data-index="3" aria-label="Row 2, column 1, empty"></button>
            <button type="button" data-index="4" aria-label="Row 2, column 2, empty"></button>
            <button type="button" data-index="5" aria-label="Row 2, column 3, empty"></button>
            <button type="button" data-index="6" aria-label="Row 3, column 1, empty"></button>
            <button type="button" data-index="7" aria-label="Row 3, column 2, empty"></button>
            <button type="button" data-index="8" aria-label="Row 3, column 3, empty"></button>
        </div>
        <button type="button" id="play-again" hidden>Play Again</button>
        <noscript><p>Enable JavaScript to play.</p></noscript>
    </main>
</body>
</html>
"use strict";

const KomiValidation = (() => {
  const { createGame, evaluateBoard, getLegalMoves, playMove, OUTCOME } = KomiGame;

  function assert(condition, message) {
    if (!condition) throw new Error(message);
  }

  // Independent geometry check: do not reuse the engine's winning-line table.
  function hasLine(board, player) {
    for (let n = 0; n < 3; n += 1) {
      if ([0, 1, 2].every(column => board[3 * n + column] === player)) return true;
      if ([0, 1, 2].every(row => board[3 * row + n] === player)) return true;
    }
    return [0, 4, 8].every(index => board[index] === player)
      || [2, 4, 6].every(index => board[index] === player);
  }

  function playSequence(moves) {
    let state = createGame();
    for (const index of moves) {
      const result = playMove(state, index);
      assert(result.accepted, `Focused sequence rejected square ${index}`);
      state = result.state;
    }
    return state;
  }

  function focusedChecks() {
    const passed = [];
    function check(name, callback) {
      callback();
      passed.push(name);
    }

    check("X row win", () => {
      assert(playSequence([0, 3, 1, 4, 2]).outcome === OUTCOME.X_WIN, "X row win");
    });
    check("O normal win", () => {
      assert(playSequence([0, 3, 1, 4, 8, 5]).outcome === OUTCOME.O_WIN, "O row win");
    });
    check("Diagonal win", () => {
      assert(playSequence([0, 1, 4, 2, 8]).outcome === OUTCOME.X_WIN, "X diagonal win");
    });
    check("Occupied square preserves state and turn", () => {
      const state = playSequence([0]);
      const before = JSON.stringify(state);
      const result = playMove(state, 0);
      assert(!result.accepted && result.reason === "OCCUPIED", "Occupied square accepted");
      assert(result.state === state && JSON.stringify(state) === before, "Rejected move changed state");
      assert(state.nextPlayer === "O", "Rejected move consumed turn");
      assert(playMove(result.state, 1).state.board[1] === "O", "O cannot move after rejection");
    });
    check("Post-terminal moves rejected for all outcomes", () => {
      for (const moves of [
        [0, 3, 1, 4, 2],
        [0, 3, 1, 4, 8, 5],
        [0, 1, 2, 4, 3, 5, 7, 6, 8],
      ]) {
        const state = playSequence(moves);
        const before = JSON.stringify(state);
        assert(getLegalMoves(state).length === 0, "Terminal state offers moves");
        for (let index = 0; index < 9; index += 1) {
          const result = playMove(state, index);
          assert(!result.accepted && result.reason === "TERMINAL" && result.state === state,
            "Terminal move was not rejected");
        }
        assert(JSON.stringify(state) === before, "Terminal state changed");
      }
    });
    check("Move-9 X normal win precedes Komi", () => {
      const before = playSequence([0, 1, 4, 2, 5, 3, 6, 7]);
      assert(before.outcome === OUTCOME.ACTIVE, "Game ended before move 9");
      const result = playMove(before, 8);
      assert(result.accepted && result.state.board.every(cell => cell !== null), "Move 9 did not fill board");
      assert(result.state.outcome === OUTCOME.X_WIN, "Komi overrode move-9 X win");
    });
    check("Full line-free board produces O_KOMI", () => {
      const state = playSequence([0, 1, 2, 4, 3, 5, 7, 6, 8]);
      assert(state.board.every(cell => cell !== null), "Komi board is not full");
      assert(!hasLine(state.board, "X") && !hasLine(state.board, "O"), "Komi board has a line");
      assert(state.outcome === OUTCOME.O_KOMI, "Missing O Komi win");
    });
    check("Invalid square indices preserve state", () => {
      const state = createGame();
      for (const index of [-1, 9, 1.5, "0", null, undefined, NaN, Infinity]) {
        const result = playMove(state, index);
        assert(!result.accepted && result.reason === "INVALID_SQUARE" && result.state === state,
          "Invalid square was not rejected");
      }
    });
    return passed;
  }
  }

  return Object.freeze({ run });
})();
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Komi tic-tac-toe exhaustive validation</title>
</head>
<body>
  <h1>Komi tic-tac-toe exhaustive validation</h1>
  <p>Runs on load. Reload to run again. No server is required.</p>
  <pre id="results">Running focused checks and every legal move sequence...</pre>
  <script src="../game.js"></script>
  <script src="exhaustive.js"></script>
  <script>
    "use strict";
    // Let the running message paint before the synchronous traversal starts.
    setTimeout(() => {
      const results = document.getElementById("results");
      try {
        const report = KomiValidation.run();
        results.textContent = "PASS\n" + JSON.stringify(report, null, 2);
      } catch (error) {
        results.textContent = "FAIL\n" + error.stack;
        console.error(error);
      }
    }, 0);
  </script>
</body>
</html>

